-- Theobroma Bakery: Supabase PostgreSQL schema
create extension if not exists pgcrypto;
create table if not exists public.categories (id bigint generated by default as identity primary key, slug text unique not null, name text not null, subtitle text, description text, icon text, image text, display_order int default 0, is_active boolean default true, created_at timestamptz default now());
create table if not exists public.products (id bigint generated by default as identity primary key, slug text unique not null, name text not null, category_id bigint references public.categories(id), category_slug text not null, subcategory text default 'all', price numeric(10,2) not null check(price>=0), is_veg boolean default true, rating numeric(2,1) default 4.8, reviews_count int default 0, badge text, description text, image text, ingredients text, stock int default 0, is_featured boolean default false, is_bestseller boolean default false, is_active boolean default true, created_at timestamptz default now());
create table if not exists public.product_variants (id bigint generated by default as identity primary key, product_id bigint not null references public.products(id) on delete cascade, variant_label text not null, price numeric(10,2) not null check(price>=0), sku text, stock int default 0);
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, phone text, role text not null default 'customer' check(role in ('customer','admin')), created_at timestamptz default now());
create table if not exists public.addresses (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, full_name text not null, phone text not null, address_line text not null, pincode text not null, city text not null, state text not null, is_default boolean default false, created_at timestamptz default now());
create table if not exists public.orders (id uuid primary key default gen_random_uuid(), order_number text unique not null, user_id uuid references auth.users(id), customer_name text not null, customer_email text not null, customer_phone text not null, delivery_address text not null, delivery_pincode text not null, delivery_city text not null, delivery_state text not null, delivery_date date, delivery_time_slot text, special_notes text, subtotal numeric(10,2) not null, discount numeric(10,2) default 0, delivery_charge numeric(10,2) default 0, total_amount numeric(10,2) not null, payment_method text default 'razorpay', payment_status text default 'Pending', razorpay_order_id text, razorpay_payment_id text, order_status text default 'Order Placed', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id bigint references public.products(id), product_name text not null, variant_label text, custom_message text, unit_price numeric(10,2) not null, quantity int not null check(quantity>0), total_price numeric(10,2) not null, product_image text);
create table if not exists public.coupons (id bigint generated by default as identity primary key, code text unique not null, discount_type text default 'percent', discount_value numeric(10,2) not null, min_order_amount numeric(10,2) default 0, max_discount numeric(10,2) default 500, is_active boolean default true, created_at timestamptz default now());
create table if not exists public.order_status_history (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, status text not null, notes text, created_at timestamptz default now());
create table if not exists public.wishlists (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, product_id bigint not null references public.products(id) on delete cascade, created_at timestamptz default now(), unique(user_id,product_id));
-- Enable RLS. Policies should be tightened before accepting real orders.
alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.product_variants enable row level security; alter table public.profiles enable row level security; alter table public.addresses enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.coupons enable row level security; alter table public.order_status_history enable row level security; alter table public.wishlists enable row level security;
create policy "Public can read active categories" on public.categories for select using (is_active=true);
create policy "Public can read active products" on public.products for select using (is_active=true);
create policy "Public can read variants" on public.product_variants for select using (true);
create policy "Users read own profile" on public.profiles for select using (auth.uid()=id);
create policy "Users update own profile" on public.profiles for update using (auth.uid()=id);
create policy "Users manage own addresses" on public.addresses for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy "Users read own orders" on public.orders for select using (auth.uid()=user_id);
create policy "Users read own order items" on public.order_items for select using (exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid()));
create policy "Users manage own wishlist" on public.wishlists for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
-- Never expose service-role or Razorpay secret keys in browser code.
